from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Ref:
    col: int
    row: int
    abs_col: bool = False
    abs_row: bool = False

__all__ = ["parse_ref", "parse_range", "to_a1"]

_REF_RE = re.compile(r"(\$?)([A-Za-z]{1,2})(\$?)([1-9][0-9]{0,3})")
_MAX_COL = 701  # ZZ, 0-based
_MAX_ROW = 9998  # 9999, 0-based


def _col_index(letters: str) -> int:
    n = 0
    for ch in letters.upper():
        n = n * 26 + (ord(ch) - 64)
    return n - 1


def _col_letters(col: int) -> str:
    out = []
    n = col + 1
    while n:
        n, r = divmod(n - 1, 26)
        out.append(chr(65 + r))
    return "".join(reversed(out))


def parse_ref(s: str) -> Ref:
    """Parse a single A1-style cell reference such as ``$B$12``."""
    m = _REF_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid cell reference: {s!r}")
    return Ref(
        _col_index(m.group(2)),
        int(m.group(4)) - 1,
        m.group(1) == "$",
        m.group(3) == "$",
    )


def _pick_axis(a_val: int, a_flag: bool, b_val: int, b_flag: bool, want_min: bool) -> tuple[int, bool]:
    if a_val == b_val:
        return a_val, a_flag
    if (a_val < b_val) == want_min:
        return a_val, a_flag
    return b_val, b_flag


def parse_range(s: str) -> tuple[Ref, Ref]:
    """Parse ``ref:ref`` into (top-left, bottom-right) with per-axis absolute flags."""
    left, sep, right = s.partition(":")
    if not sep:
        raise ValueError(f"invalid range: {s!r}")
    a = parse_ref(left)
    b = parse_ref(right)
    c1, f1 = _pick_axis(a.col, a.abs_col, b.col, b.abs_col, True)
    r1, g1 = _pick_axis(a.row, a.abs_row, b.row, b.abs_row, True)
    c2, f2 = _pick_axis(a.col, a.abs_col, b.col, b.abs_col, False)
    r2, g2 = _pick_axis(a.row, a.abs_row, b.row, b.abs_row, False)
    return Ref(c1, r1, f1, g1), Ref(c2, r2, f2, g2)


def to_a1(ref: Ref) -> str:
    """Format a Ref as an uppercase A1-style reference with ``$`` flags."""
    if not (0 <= ref.col <= _MAX_COL and 0 <= ref.row <= _MAX_ROW):
        raise ValueError(f"reference out of range: {ref!r}")
    col = ("$" if ref.abs_col else "") + _col_letters(ref.col)
    row = ("$" if ref.abs_row else "") + str(ref.row + 1)
    return col + row

